import numpy as np, itertools, random
def unit(v):
    v=np.asarray(v,dtype=float); return v/np.linalg.norm(v)
atoms=[]; bonds=[]
def add(el,p,parent=None):
    atoms.append([el,np.array(p,float)])
    i=len(atoms)-1
    if parent is not None: bonds.append((parent,i))
    return i
def pos(i): return atoms[i][1]
def place_two(c,d1,d2,b):
    d1=unit(d1);d2=unit(d2); s=-unit(d1+d2); p=unit(np.cross(d1,d2)); a=np.deg2rad(54.74)
    return [c+b*(np.cos(a)*s+np.sin(a)*p), c+b*(np.cos(a)*s-np.sin(a)*p)]
def tripod(ci,parent,blen,els,phase=0.0,ang=109.47):
    C=pos(ci); u=unit(C-pos(parent))
    tmp=np.array([1.,0,0])
    if abs(np.dot(tmp,u))>0.9: tmp=np.array([0,1.,0])
    p1=unit(np.cross(u,tmp)); p2=np.cross(u,p1); a=np.deg2rad(180-ang)
    out=[]
    for k,el in enumerate(els):
        phi=np.deg2rad(phase+120*k)
        d=np.cos(a)*u+np.sin(a)*(np.cos(phi)*p1+np.sin(phi)*p2)
        out.append(add(el,C+blen[k]*d,ci))
    return out

Zr=add('Zr',[0,0,0])
cen=np.array([0,0,2.2]); R=1.19
azi={'C1':162,'C2':90,'C3':18,'C4':234,'C5':306}
cp={}
for k,a in azi.items():
    ar=np.deg2rad(a); cp[k]=add('C',cen+R*np.array([np.cos(ar),np.sin(ar),0.]))
order=['C1','C2','C3','C4','C5']
ringseq=['C1','C2','C3','C5','C4']  # adjacency by angle: 18,90,162,234,306
seq=[('C3','C2'),('C2','C1'),('C1','C4'),('C4','C5'),('C5','C3')]
for a,b in seq: bonds.append((cp[a],cp[b]))
for k in ['C2','C4','C5']:
    d=unit(pos(cp[k])-cen+np.array([0,0,0.12])); add('H',pos(cp[k])+1.08*d,cp[k])

arms=[]
def build_arm(cpkey,sign,P_phi):
    cC=cp[cpkey]
    Si=add('Si',pos(cC)+1.87*unit(pos(cC)-cen),cC)
    th=np.deg2rad(108); ph=np.deg2rad(P_phi)
    P=add('P',2.78*np.array([np.sin(th)*np.cos(ph),np.sin(th)*np.sin(ph),np.cos(th)]))
    bonds.append((Zr,P))
    vSi=pos(Si);vP=pos(P); e=unit(vP-vSi); L=np.linalg.norm(vP-vSi); M=0.5*(vSi+vP)
    h=np.sqrt(max(1.88**2-(L/2)**2,0.4))
    r=np.array([sign*0.9,0.3,0.0]); rp=unit(r-np.dot(r,e)*e)
    Cb=add('C',M+h*rp,Si); bonds.append((Cb,P))
    for hh in place_two(pos(Cb),pos(Si)-pos(Cb),pos(P)-pos(Cb),1.09): add('H',hh,Cb)
    for m in place_two(pos(Si),pos(cC)-pos(Si),pos(Cb)-pos(Si),1.87):
        mi=add('C',m,Si); tripod(mi,Si,[1.09]*3,['H']*3)
    ipc=[]
    for ip in place_two(pos(P),pos(Cb)-pos(P),pos(Zr)-pos(P),1.86):
        ci=add('C',ip,P)
        ms=tripod(ci,P,[1.53,1.53,1.10],['C','C','H'])
        for mi in ms[:2]: tripod(mi,ci,[1.09]*3,['H']*3)
        ipc.append(ci)
    arms.append((Si,P,Cb,ipc))
build_arm('C3',+1,18.0); build_arm('C1',-1,162.0)
def sph(th,ph,r):
    t=np.deg2rad(th);p=np.deg2rad(ph)
    return r*np.array([np.sin(t)*np.cos(p),np.sin(t)*np.sin(p),np.cos(t)])
Cme=add('C',sph(103,215,2.30),Zr); tripod(Cme,Zr,[1.09]*3,['H']*3)
add('Cl',sph(103,325,2.45),Zr)

N=len(atoms); X=np.array([a[1] for a in atoms]); els=[a[0] for a in atoms]
# graph
adj={i:set() for i in range(N)}
for i,j in bonds: adj[i].add(j); adj[j].add(i)
# bond-distance matrix (BFS limited)
import collections
BD=np.full((N,N),9)
for s in range(N):
    dq=collections.deque([(s,0)]); seen={s:0}
    while dq:
        u,d=dq.popleft(); BD[s,u]=d
        if d<3:
            for v in adj[u]:
                if v not in seen: seen[v]=d+1; dq.append((v,d+1))
rad={'H':1.1,'C':1.7,'Si':2.0,'P':1.9,'Cl':1.75,'Zr':2.0}
pairs=[(i,j) for i in range(N) for j in range(i+1,N) if BD[i,j]>3]
pi=np.array([p[0] for p in pairs]); pj=np.array([p[1] for p in pairs])
r0=np.array([0.80*(rad[els[i]]+rad[els[j]]) for i,j in pairs])
def energy(Y):
    d=np.linalg.norm(Y[pi]-Y[pj],axis=1)
    ov=np.clip(r0-d,0,None)
    return (ov**2).sum()
# rotatable bonds: (a,b,moving set) rotate subtree beyond b
def subtree(a,b):
    s={b}; dq=collections.deque([b])
    while dq:
        u=dq.popleft()
        for v in adj[u]:
            if v!=a and v not in s: s.add(v); dq.append(v)
    return sorted(s)
rot=[]
for i,j in bonds:
    if els[i]=='H' or els[j]=='H': continue
    for a,b in ((i,j),(j,i)):
        st=subtree(a,b)
        if len(st)>1 and a not in st and len(st)<N//2:
            rot.append((a,b,np.array(st))); break
def rotate(Y,a,b,st,ang):
    axis=unit(Y[b]-Y[a]); o=Y[b]
    v=Y[st]-o; c=np.cos(ang); s=np.sin(ang)
    Y=Y.copy()
    Y[st]=o+v*c+np.cross(axis,v)*s+np.outer(v@axis,axis)*(1-c)
    return Y
best=X.copy(); E=energy(best)
random.seed(1)
for it in range(6000):
    a,b,st=random.choice(rot)
    ang=np.deg2rad(random.choice([120,-120,60,-60,30,-30,15,-15,180,10,-10]))
    Y=rotate(best,a,b,st,ang); e=energy(Y)
    if e<E-1e-9: best,E=Y,e
print('E',E)
with open('start.xyz','w') as f:
    f.write(f"{N}\nguess\n")
    for el,p in zip(els,best): f.write(f"{el} {p[0]:.4f} {p[1]:.4f} {p[2]:.4f}\n")
D=np.linalg.norm(best[pi]-best[pj],axis=1)
print('min nonbonded',D.min())
